private void ReportFooter_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
  ReportFooter.Controls.Clear();

            XRTable totalet = new XRTable();
            totalet.BeginInit();
            totalet.LocationF = new DevExpress.Utils.PointFloat(227.88F, 0F);
            totalet.WidthF = 604.3F;
            XRTableRow rr1 = new XRTableRow();
            rr1.HeightF = 30F;
            XRTableCell totali = new XRTableCell();
            totali.Text = "Totali sipas monedhave";
            totali.TextAlignment = DevExpress.XtraPrinting.TextAlignment.TopCenter;
            totali.Font = new System.Drawing.Font("Times New Roman", 10F, System.Drawing.FontStyle.Bold);
            totali.ForeColor = System.Drawing.Color.Green;
            totali.WidthF = 167.63F;
