            viza.BorderColor = System.Drawing.Color.Black;
            viza.BorderWidth = 2;
            viza.WidthF = 436.67f;
            rr1.Cells.Add(viza);

            totalet.Rows.Add(rr1);
            for (int i = 0; i < nrmon; i++)
