                detmeparshem.Text = String.Format("{0:n2}", totdetmeparshem[i]);
                detmeparshem.XlsxFormatString = "#,##0.00";
                totdetmeparshem[i] = 0;
                detmeparshem.TextAlignment = DevExpress.XtraPrinting.TextAlignment.TopRight;
                detmeparshem.Font = new System.Drawing.Font("Times New Roman", 10F, System.Drawing.FontStyle.Bold);
                detmeparshem.ForeColor = System.Drawing.Color.Green;
                rr.Cells.Add(detmeparshem);

                XRTableCell faturuar = new XRTableCell();
