                totfaturuar[i] = 0;
                faturuar.TextAlignment = DevExpress.XtraPrinting.TextAlignment.TopRight;
                faturuar.Font = new System.Drawing.Font("Times New Roman", 10F, System.Drawing.FontStyle.Bold);
                faturuar.ForeColor = System.Drawing.Color.Green;
                rr.Cells.Add(faturuar);

                XRTableCell arketuar = new XRTableCell();
                arketuar.WidthF = 107.21F;
                arketuar.Text = String.Format("{0:n2}", totarketuar[i]);
                arketuar.XlsxFormatString = "#,##0.00";
                totarketuar[i] = 0;
                arketuar.TextAlignment = DevExpress.XtraPrinting.TextAlignment.TopRight;
                arketuar.Font = new System.Drawing.Font("Times New Roman", 10F, System.Drawing.FontStyle.Bold);
                arketuar.ForeColor = System.Drawing.Color.Green;
                rr.Cells.Add(arketuar);

                XRTableCell detyrimi = new XRTableCell();
