private void Rap_SituacionineMonedheneKlientit_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
var parameters = AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]);
 var formati = parameters.Find(param => param.Emri == "filterFormatNumri");
	shifraPasPresjes = (formati != null) ? formati.Vlera : "2";	
	AlphaWebReports.raporteUtil.vendosFormatinEFushesSeRaportit("{0:N"+shifraPasPresjes+"}",0.ToString("N" + shifraPasPresjes), true, xrTableCell8);

xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);
}


private void xrTableCell1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);
  if (GetCurrentColumnValue("KODKLIENTFURNITOR") != null)
            {
                 xrTableCell1.NavigateUrl = "javascript:window.myFaqeCelje.hapFaqeNeTabTeRi('RaportiShpejte.aspx?scopeID="+parametraRaporti.ScopeID+"&guidString=" + parametraRaporti.GuidString + "&idraporti=" + parametraRaporti.IdSubRaporti + "&filterFurnitor=" + GetCurrentColumnValue("KODKLIENTFURNITOR") + "&printo=0&Sesioni=true')";
                    xrTableCell1.Target = "_self";
            }
}


private void xrTableCell3_AfterPrint(object sender, System.EventArgs e) {
  bool ugjet = false;
            if (nrmon!=0)
            for(int a=0; a<=nrmon; a++){
                if (monedha[a] == xrTableCell3.Text) { ugjet = true; break; }
            }
            if (!ugjet)
            {
                monedha[nrmon] = xrTableCell3.Text;
                nrmon++;
            }
}

private void xrTableCell5_AfterPrint(object sender, System.EventArgs e) {
   for (int a = 0; a <= nrmon; a++)
            {
                if (GetCurrentColumnValue("MONEDHAKOD") != null)
                {
                     if (monedha[a] == GetCurrentColumnValue("MONEDHAKOD").ToString()) { totdetmeparshem[a] += Convert.ToDouble(xrTableCell5.Text); }
                }

            }
}

private void xrTableCell6_AfterPrint(object sender, System.EventArgs e) {
 for (int a = 0; a <= nrmon; a++)
            {
                if (GetCurrentColumnValue("MONEDHAKOD") != null)
                {
                    if (monedha[a] == GetCurrentColumnValue("MONEDHAKOD").ToString()) { totfaturuar[a] += Convert.ToDouble(xrTableCell6.Text); }
                }
            }
}

private void xrTableCell7_AfterPrint(object sender, System.EventArgs e) {
for (int a = 0; a <= nrmon; a++)
            {
                if (GetCurrentColumnValue("MONEDHAKOD") != null)
                {
                    if (monedha[a] == GetCurrentColumnValue("MONEDHAKOD").ToString()) { totarketuar[a] += Convert.ToDouble(xrTableCell7.Text); }
