}

private void xrTableCell8_AfterPrint(object sender, System.EventArgs e) {

            if (xrTableCell8.Text != null && xrTableCell8.Text != "")
               detyrimi += Convert.ToDouble(xrTableCell8.Text);
            for (int a = 0; a <= nrmon; a++)
            {
                if (GetCurrentColumnValue("MONEDHAKOD") != null)
                {
                  if (monedha[a] == GetCurrentColumnValue("MONEDHAKOD").ToString()) { totdetyrimi[a] += Convert.ToDouble(xrTableCell8.Text); }
                }
           }
}
